-- DISPOSABLE FIXTURE ONLY. Never run against a Supabase project.
create role anon;create role authenticated;create role service_role;
create schema auth;grant usage on schema auth to authenticated;
create function auth.uid() returns uuid language sql stable as $$select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;
create table public.profiles(id uuid primary key,role text,is_active boolean,full_name text,email text);
create function public.current_user_role() returns text language sql stable security definer as $$select role from public.profiles where id=auth.uid() and is_active$$;
create table public.activity_log(id bigint generated by default as identity primary key,user_id uuid references public.profiles(id),action text not null,target text not null,created_at timestamptz not null default now());
create function public.write_required_balance_audit(text,text) returns void language plpgsql as $$begin
 if auth.uid() is null or coalesce(public.current_user_role(),'') not in ('admin','secretary','treasurer') then raise exception 'Staff actor required' using errcode='42501';end if;
 insert into public.activity_log(user_id,action,target) values(auth.uid(),$1,$2);end$$;
create table public.payments(id bigint primary key,amount_paid numeric);
insert into public.payments values(1,100);
create schema extensions;
create function extensions.digest(text,text) returns bytea language sql immutable as $$select sha256(convert_to($1,'UTF8'))$$;
create schema vault;create table vault.secrets(id uuid primary key default gen_random_uuid(),name text unique,secret text);
create view vault.decrypted_secrets as select id,name,secret as decrypted_secret from vault.secrets;
create function vault.create_secret(text,text,text) returns uuid language sql as $$insert into vault.secrets(secret,name)values($1,$2)returning id$$;
create schema net;
create function net.http_post(url text,body jsonb default '{}',params jsonb default '{}',headers jsonb default '{}',timeout_milliseconds integer default 1000)returns bigint language sql as $$select 1::bigint$$;
create schema storage;grant usage on schema storage to anon,authenticated;
create table storage.buckets(id text primary key,public boolean);
create table storage.objects(id uuid primary key default gen_random_uuid(),bucket_id text,name text,metadata jsonb);
alter table storage.objects enable row level security;
grant select on storage.objects to anon;
grant select,insert,update,delete on storage.objects to authenticated;
-- Deliberately broad preexisting policies prove new archive guards cannot be bypassed.
create policy fixture_broad_reads on storage.objects for select to anon,authenticated using(true);
create policy fixture_broad_writes on storage.objects for all to authenticated using(true)with check(true);
create schema cron;create table cron.job(jobid bigint generated always as identity primary key,jobname text unique,schedule text,command text);
create function cron.schedule(text,text,text)returns bigint language sql as $$insert into cron.job(jobname,schedule,command)values($1,$2,$3)returning jobid$$;
create function cron.unschedule(bigint)returns boolean language sql as $$delete from cron.job where jobid=$1 returning true$$;
select cron.schedule('bill-monthly-dues','5 16 * * *','select public.bill_monthly_dues()');
select cron.schedule('post-late-penalties','10 16 * * *','select public.post_due_penalties()');
